<?php
namespace App\Http\Controllers; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\Rule;
class UserController extends Controller {public function index(Request $r){$users=User::when($r->search,fn($q,$s)=>$q->where(fn($z)=>$z->where('name','like',"%$s%")->orWhere('email','like',"%$s%")))->when($r->role,fn($q,$x)=>$q->where('role',$x))->orderBy('name')->paginate(10)->withQueryString();return view('users.index',compact('users'));} public function create(){return view('users.form',['user'=>new User]);} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users,email','password'=>'required|min:8','role'=>'required|in:admin,petugas,nasabah','phone'=>'nullable|max:30','address'=>'nullable|max:500']);$d['password']=Hash::make($d['password']);$d['is_active']=true;User::create($d);return redirect()->route('users.index')->with('success','Pengguna berhasil ditambahkan.');} public function edit(User $user){return view('users.form',compact('user'));} public function update(Request $r,User $user){$d=$r->validate(['name'=>'required|string|max:100','email'=>['required','email',Rule::unique('users','email')->ignore($user->id)],'password'=>'nullable|min:8','role'=>'required|in:admin,petugas,nasabah','phone'=>'nullable|max:30','address'=>'nullable|max:500','is_active'=>'nullable|boolean']);if(empty($d['password']))unset($d['password']);else$d['password']=Hash::make($d['password']);$d['is_active']=$r->boolean('is_active');$user->update($d);return redirect()->route('users.index')->with('success','Pengguna diperbarui.');} public function destroy(User $user){abort_if($user->id===auth()->id(),422,'Tidak dapat menghapus akun sendiri.');$user->delete();return back()->with('success','Pengguna dihapus (soft delete).');}}
